    {
      id: "c2wd-evidence99",
      revision: "r1",
      mode: "evidence-detective",
      prompt: "Winter break counts in an Ontario city spike in the coldest week each year, but one district spikes two weeks before the coldest week, every year.",
      topicId: "break-pattern-analysis",
      level: "class1",
      assumptions: "Fictional 10 year break and temperature records by district. The early district is the highest elevation district, served by the tank that also shows the earliest ice formation. Frost depth data is collected by the roads department.",
      evidence: [
        {
          id: "ev1",
          label: "City wide breaks peak in the week of lowest temperature, tracking frost penetration under roads."
        },
        {
          id: "ev2",
          label: "The hill district breaks peak two weeks earlier, when its tank and exposed mains have already reached their coldest water temperatures."
        },
        {
          id: "ev3",
          label: "Hill district water temperature falls fastest in autumn because its tank is small and its mains are shallowest in the city."
        },
        {
          id: "ev4",
          label: "Break types in the hill district are mostly circumferential cracks, the pattern associated with thermal contraction stress."
        },
        {
          id: "ev5",
          label: "Pressure records show no district specific surge pattern in the early break weeks."
        }
      ],
      inference: {
        id: "inference",
        prompt: "Which explanation is best supported by all of the observations?",
        options: [
          {
            id: "inf-a",
            label: "The hill district crews report breaks two weeks late and dates are shifted"
          },
          {
            id: "inf-b",
            label: "A pressure transient program runs in the hill district each autumn"
          },
          {
            id: "inf-c",
            label: "Hill district mains are a unique material that fails early"
          },
          {
            id: "inf-d",
            label: "The hill district cools faster, so its thermal contraction break season simply arrives earlier than the frost driven city peak"
          }
        ],
        correctOptionId: "inf-d",
        explanation: "Circumferential crack type, fastest water cooling, and shallow mains all align on thermal timing, and pressure records exclude a surge program. Reporting delay would shift all break types and dates, not concentrate one crack type in one season window."
      },
      nextClue: {
        id: "next-clue",
        prompt: "Which planning use should be made of the offset pattern?",
        options: [
          {
            id: "nc-a",
            label: "Advance the hill district winter readiness, leak patrols, and repair stock by two weeks in the seasonal plan, based on its own break history"
          },
          {
            id: "nc-b",
            label: "Move the whole city winter plan two weeks earlier"
          },
          {
            id: "nc-c",
            label: "Investigate the hill district reporting office for date errors"
          }
        ],
        correctOptionId: "nc-a",
        explanation: "District specific readiness matches resources to measured risk timing. Moving the whole city wastes readiness where the peak is later, and the records are corroborated by water temperature data, not a clerical pattern."
      },
      clueText: {
        "nc-a": "The seasonal plan now staggers readiness by district, and hill district response times improve in its early peak.",
        "nc-b": "City wide advance would idle crews in districts whose peak still arrives with the deep frost.",
        "nc-c": "Temperature and crack type data confirm the dates are real, not a reporting artefact."
      }
    }
